export default {"numero":33,"slug":"trust-and-safety","modelo":false,"categoria":"seguranca","titulo":"TRUST & SAFETY POLICY","curto":"Confiança e Segurança","versao":"1.0","entradaEmVigor":"14-09-2026","blocos":[{"tipo":"h3","texto":"VENUE1HUB®"},{"tipo":"p","c":[{"t":"Versão:","b":true},{"t":" 1.0\n"},{"t":"Data de entrada em vigor:","b":true},{"t":" 14-09-2026"}]},{"tipo":"p","c":"A presente Trust & Safety Policy (“Política de Confiança e Segurança”) estabelece os princípios, regras e mecanismos utilizados pela Venue1Hub® para promover a segurança, confiança e integridade da Plataforma e das interações entre os seus utilizadores."},{"tipo":"p","c":"A segurança é uma responsabilidade partilhada."},{"tipo":"p","c":"A Venue1Hub disponibiliza ferramentas, processos e mecanismos de prevenção e resposta, mas Hosts, Clientes, Prestadores e restantes utilizadores continuam responsáveis pelo cumprimento das suas próprias obrigações e por adotar comportamentos adequados e seguros."},{"tipo":"p","c":"Esta Política aplica-se, conforme relevante, a:"},{"tipo":"lista","chave":"3","itens":[{"n":0,"c":"Clientes;"},{"n":0,"c":"Hosts;"},{"n":0,"c":"Business Hosts;"},{"n":0,"c":"Prestadores;"},{"n":0,"c":"Parceiros;"},{"n":0,"c":"participantes;"},{"n":0,"c":"representantes;"},{"n":0,"c":"outros utilizadores da Plataforma."}]},{"tipo":"p","c":"Complementa:"},{"tipo":"lista","chave":"7","itens":[{"n":0,"c":"os Termos de Serviço Venue1Hub;"},{"n":0,"c":"os Termos do Cliente / Guest Terms;"},{"n":0,"c":"os Termos do Anfitrião / Host Terms;"},{"n":0,"c":"os Termos para Business Hosts / Anfitriões Profissionais;"},{"n":0,"c":"os Termos de Prestadores / Parceiros;"},{"n":0,"c":"a Política de Utilização Aceitável / Atividades Proibidas;"},{"n":0,"c":"a Política de Conteúdos;"},{"n":0,"c":"a Política de Verificação de Identidade;"},{"n":0,"c":"a Política de Suspensão e Encerramento de Contas;"},{"n":0,"c":"a Política Anti-Circumvention;"},{"n":0,"c":"a Política de Avaliações e Reviews;"},{"n":0,"c":"o Procedimento Notice & Action;"},{"n":0,"c":"a Política de Danos, Cauções e Reclamações;"},{"n":0,"c":"a Política de Resolução de Conflitos;"},{"n":0,"c":"os Termos de Pagamento;"},{"n":0,"c":"a Política de Privacidade;"},{"n":0,"c":"as restantes políticas aplicáveis."}]},{"tipo":"h2","texto":"1. IDENTIFICAÇÃO DA PLATAFORMA"},{"tipo":"p","c":"A Venue1Hub® é uma plataforma digital operada pela:"},{"tipo":"p","c":[{"t":"EdgeHub OÜ\n","b":true},{"t":"Sociedade constituída ao abrigo da legislação da República da Estónia\nNúmero de registo: "},{"t":"17515912\n","b":true},{"t":"Sede: Tallinn, Estónia\nE-mail: "},{"t":"mail@venue1hub.com\n","b":true},{"t":"Website:"},{"t":" www.venue1hub.com","href":"http://www.venue1hub.com/"}]},{"tipo":"h2","texto":"2. OBJETIVO"},{"tipo":"p","c":"Esta Política tem como objetivos:"},{"tipo":"p","c":"a) promover um marketplace seguro e confiável;"},{"tipo":"p","c":"b) prevenir fraude, abuso e atividades ilegais;"},{"tipo":"p","c":"c) proteger Hosts, Clientes, Prestadores e terceiros;"},{"tipo":"p","c":"d) promover utilização segura dos Espaços;"},{"tipo":"p","c":"e) definir comportamentos que podem justificar intervenção;"},{"tipo":"p","c":"f) explicar como podem ser comunicados incidentes;"},{"tipo":"p","c":"g) estabelecer princípios de investigação e resposta;"},{"tipo":"p","c":"h) articular os mecanismos de Trust & Safety com pagamentos, reservas, conteúdos e Contas;"},{"tipo":"p","c":"i) proteger a integridade da Plataforma."},{"tipo":"h2","texto":"3. PRINCÍPIO DE SEGURANÇA"},{"tipo":"p","c":"A Venue1Hub procura integrar segurança ao longo de todo o ciclo da experiência:"},{"tipo":"p","c":[{"t":"Identidade","b":true}]},{"tipo":"p","c":"↓"},{"tipo":"p","c":[{"t":"Listing","b":true}]},{"tipo":"p","c":"↓"},{"tipo":"p","c":[{"t":"Reserva","b":true}]},{"tipo":"p","c":"↓"},{"tipo":"p","c":[{"t":"Pagamento","b":true}]},{"tipo":"p","c":"↓"},{"tipo":"p","c":[{"t":"Utilização do Espaço","b":true}]},{"tipo":"p","c":"↓"},{"tipo":"p","c":[{"t":"Serviços Complementares","b":true}]},{"tipo":"p","c":"↓"},{"tipo":"p","c":[{"t":"Problema / Incidente","b":true}]},{"tipo":"p","c":"↓"},{"tipo":"p","c":[{"t":"Trust & Safety","b":true}]},{"tipo":"p","c":"↓"},{"tipo":"p","c":[{"t":"Resolução","b":true}]},{"tipo":"p","c":"↓"},{"tipo":"p","c":[{"t":"Registo e Evidência","b":true}]},{"tipo":"h2","texto":"4. SEGURANÇA COMO RESPONSABILIDADE PARTILHADA"},{"tipo":"p","c":"A Venue1Hub disponibiliza mecanismos de segurança, mas não substitui:"},{"tipo":"p","c":"a) a responsabilidade do Host pelo Espaço;"},{"tipo":"p","c":"b) a responsabilidade do Cliente pela sua atividade;"},{"tipo":"p","c":"c) a responsabilidade dos Prestadores pelos serviços que executam;"},{"tipo":"p","c":"d) as obrigações das autoridades;"},{"tipo":"p","c":"e) os serviços de emergência;"},{"tipo":"p","c":"f) as obrigações legais próprias de cada utilizador."},{"tipo":"h2","texto":"5. PAPEL DA VENUE1HUB"},{"tipo":"p","c":"A Venue1Hub poderá atuar para:"},{"tipo":"p","c":"a) verificar determinados utilizadores;"},{"tipo":"p","c":"b) prevenir fraude;"},{"tipo":"p","c":"c) analisar comportamentos suspeitos;"},{"tipo":"p","c":"d) receber denúncias;"},{"tipo":"p","c":"e) aplicar medidas de proteção;"},{"tipo":"p","c":"f) remover conteúdos;"},{"tipo":"p","c":"g) suspender Listings;"},{"tipo":"p","c":"h) restringir Contas;"},{"tipo":"p","c":"i) apoiar a resolução de incidentes;"},{"tipo":"p","c":"j) cooperar com autoridades quando legalmente exigido."},{"tipo":"h2","texto":"6. LIMITES DA VENUE1HUB"},{"tipo":"p","c":"A Venue1Hub não consegue garantir que:"},{"tipo":"p","c":"a) nunca ocorrerão incidentes;"},{"tipo":"p","c":"b) todos os utilizadores agirão corretamente;"},{"tipo":"p","c":"c) todos os Espaços estarão permanentemente livres de riscos;"},{"tipo":"p","c":"d) todas as informações falsas serão detetadas previamente;"},{"tipo":"p","c":"e) todos os conflitos serão evitados."},{"tipo":"p","c":"Os processos de Trust & Safety destinam-se a reduzir riscos e responder adequadamente quando surgem problemas."},{"tipo":"h2","texto":"7. VERIFICAÇÃO DE IDENTIDADE"},{"tipo":"p","c":"A Venue1Hub poderá exigir diferentes níveis de identificação ou verificação."},{"tipo":"p","c":"Estes processos encontram-se regulados pela Política de Verificação de Identidade."},{"tipo":"h2","texto":"8. HOSTS"},{"tipo":"p","c":"Hosts poderão ser sujeitos a verificação antes de:"},{"tipo":"p","c":"a) publicar;"},{"tipo":"p","c":"b) aceitar Reservas;"},{"tipo":"p","c":"c) receber pagamentos;"},{"tipo":"p","c":"d) receber payouts."},{"tipo":"h2","texto":"9. BUSINESS HOSTS"},{"tipo":"p","c":"Business Hosts poderão ter de fornecer informação empresarial adicional."},{"tipo":"h2","texto":"10. CLIENTES"},{"tipo":"p","c":"Clientes poderão ser sujeitos a verificação quando necessário por razões de:"},{"tipo":"p","c":"a) fraude;"},{"tipo":"p","c":"b) segurança;"},{"tipo":"p","c":"c) pagamento;"},{"tipo":"p","c":"d) risco;"},{"tipo":"p","c":"e) obrigação legal."},{"tipo":"h2","texto":"11. PRESTADORES"},{"tipo":"p","c":"Prestadores poderão estar sujeitos a:"},{"tipo":"p","c":"a) KYC/KYB;"},{"tipo":"p","c":"b) verificação empresarial;"},{"tipo":"p","c":"c) confirmação de licenças;"},{"tipo":"p","c":"d) confirmação de seguros;"},{"tipo":"p","c":"e) outros requisitos adequados à atividade."},{"tipo":"h2","texto":"12. VERIFICAÇÃO NÃO É GARANTIA"},{"tipo":"p","c":"Uma identidade ou empresa identificada como “verificada” apenas significa que determinado processo de verificação foi concluído."},{"tipo":"p","c":"Não significa garantia absoluta de:"},{"tipo":"p","c":"a) honestidade;"},{"tipo":"p","c":"b) segurança;"},{"tipo":"p","c":"c) comportamento futuro;"},{"tipo":"p","c":"d) solvabilidade;"},{"tipo":"p","c":"e) legalidade permanente;"},{"tipo":"p","c":"f) qualidade."},{"tipo":"h2","texto":"13. VENUE1HUB® VERIFIED"},{"tipo":"p","c":[{"t":"Um eventual programa "},{"t":"Venue1Hub® Verified","b":true},{"t":" será distinto da simples verificação de identidade."}]},{"tipo":"p","c":"Os critérios aplicáveis serão definidos separadamente."},{"tipo":"h2","texto":"14. SEGURANÇA DOS LISTINGS"},{"tipo":"p","c":"Os Listings deverão representar corretamente os Espaços."},{"tipo":"p","c":"Hosts são responsáveis por:"},{"tipo":"p","c":"a) informação verdadeira;"},{"tipo":"p","c":"b) fotografias adequadas;"},{"tipo":"p","c":"c) capacidade;"},{"tipo":"p","c":"d) características;"},{"tipo":"p","c":"e) regras;"},{"tipo":"p","c":"f) limitações;"},{"tipo":"p","c":"g) riscos relevantes conhecidos."},{"tipo":"h2","texto":"15. RISCOS CONHECIDOS"},{"tipo":"p","c":"O Host deverá informar sobre condições materiais que possam afetar a segurança da utilização."},{"tipo":"h2","texto":"16. SEGURANÇA FÍSICA DO ESPAÇO"},{"tipo":"p","c":"O Host é responsável por assegurar, nos termos aplicáveis, que o Espaço reúne as condições necessárias à utilização que anuncia."},{"tipo":"h2","texto":"17. CAPACIDADE"},{"tipo":"p","c":"Não deverá ser excedida a capacidade:"},{"tipo":"p","c":"a) anunciada;"},{"tipo":"p","c":"b) autorizada;"},{"tipo":"p","c":"c) legalmente admissível."},{"tipo":"h2","texto":"18. SAÍDAS DE EMERGÊNCIA"},{"tipo":"p","c":"Os utilizadores não deverão bloquear:"},{"tipo":"p","c":"a) saídas;"},{"tipo":"p","c":"b) corredores;"},{"tipo":"p","c":"c) acessos de emergência;"},{"tipo":"p","c":"d) equipamentos de segurança."},{"tipo":"h2","texto":"19. EQUIPAMENTOS DE SEGURANÇA"},{"tipo":"p","c":"Não é permitido inutilizar ou manipular indevidamente:"},{"tipo":"p","c":"a) alarmes;"},{"tipo":"p","c":"b) extintores;"},{"tipo":"p","c":"c) detetores;"},{"tipo":"p","c":"d) sinalização;"},{"tipo":"p","c":"e) outros equipamentos de segurança."},{"tipo":"h2","texto":"20. SPACE RULES"},{"tipo":"p","c":"As Space Rules constituem uma parte importante do modelo de segurança da Venue1Hub."},{"tipo":"p","c":"Clientes deverão respeitá-las durante toda a utilização."},{"tipo":"h2","texto":"21. FINALIDADE DA RESERVA"},{"tipo":"p","c":"O Cliente deverá indicar corretamente a finalidade da utilização quando solicitado."},{"tipo":"h2","texto":"22. ALTERAÇÃO MATERIAL DA ATIVIDADE"},{"tipo":"p","c":"Uma atividade materialmente diferente daquela declarada poderá exigir nova autorização."},{"tipo":"h2","texto":"23. ATIVIDADES DE RISCO"},{"tipo":"p","c":"Atividades com risco acrescido poderão:"},{"tipo":"p","c":"a) ser proibidas;"},{"tipo":"p","c":"b) exigir autorização;"},{"tipo":"p","c":"c) exigir documentação;"},{"tipo":"p","c":"d) exigir seguro;"},{"tipo":"p","c":"e) exigir condições especiais."},{"tipo":"h2","texto":"24. ATIVIDADES ILEGAIS"},{"tipo":"p","c":"É proibida qualquer utilização da Venue1Hub ou dos Espaços para atividades ilegais."},{"tipo":"h2","texto":"25. VIOLÊNCIA"},{"tipo":"p","c":"A Venue1Hub não tolera:"},{"tipo":"p","c":"a) violência;"},{"tipo":"p","c":"b) ameaças credíveis;"},{"tipo":"p","c":"c) intimidação grave;"},{"tipo":"p","c":"d) agressões."},{"tipo":"h2","texto":"26. RISCO IMINENTE"},{"tipo":"p","c":"Quando exista risco imediato para pessoas, deverá ser dada prioridade à segurança física."},{"tipo":"h2","texto":"27. SERVIÇOS DE EMERGÊNCIA"},{"tipo":"p","c":"Em caso de emergência imediata, o utilizador deverá contactar diretamente os serviços de emergência competentes."},{"tipo":"p","c":"A Venue1Hub não substitui:"},{"tipo":"p","c":"a) polícia;"},{"tipo":"p","c":"b) bombeiros;"},{"tipo":"p","c":"c) emergência médica;"},{"tipo":"p","c":"d) proteção civil;"},{"tipo":"p","c":"e) outros serviços públicos de emergência."},{"tipo":"h2","texto":"28. APÓS CONTACTAR EMERGÊNCIA"},{"tipo":"p","c":"Depois de assegurada a resposta urgente necessária, o incidente poderá ser comunicado à Venue1Hub assim que razoavelmente possível."},{"tipo":"h2","texto":"29. ASSÉDIO"},{"tipo":"p","c":"Não é permitido utilizar a Venue1Hub para:"},{"tipo":"p","c":"a) perseguir;"},{"tipo":"p","c":"b) intimidar;"},{"tipo":"p","c":"c) assediar;"},{"tipo":"p","c":"d) ameaçar;"},{"tipo":"p","c":"e) exercer pressão abusiva sobre terceiros."},{"tipo":"h2","texto":"30. ASSÉDIO SEXUAL"},{"tipo":"p","c":"Comportamento sexual não solicitado, intimidação sexual ou assédio sexual são incompatíveis com as regras da Plataforma."},{"tipo":"h2","texto":"31. DISCRIMINAÇÃO"},{"tipo":"p","c":"Utilizadores deverão cumprir as regras de não discriminação e a legislação aplicável."},{"tipo":"h2","texto":"32. DISCURSO DE ÓDIO E DESUMANIZAÇÃO"},{"tipo":"p","c":"Conteúdos ou comportamentos destinados a promover violência, ódio ou desumanização de pessoas ou grupos poderão justificar intervenção."},{"tipo":"h2","texto":"33. EXPLORAÇÃO"},{"tipo":"p","c":"É proibida qualquer utilização da Plataforma associada a:"},{"tipo":"p","c":"a) tráfico de pessoas;"},{"tipo":"p","c":"b) exploração sexual;"},{"tipo":"p","c":"c) trabalho forçado;"},{"tipo":"p","c":"d) outras formas de exploração ilícita."},{"tipo":"h2","texto":"34. MENORES"},{"tipo":"p","c":"É estritamente proibido qualquer comportamento relacionado com exploração ou abuso de menores."},{"tipo":"p","c":"Situações relevantes poderão ser comunicadas às autoridades competentes nos termos legalmente aplicáveis."},{"tipo":"h2","texto":"35. ARMAS"},{"tipo":"p","c":"A presença ou utilização de armas deverá respeitar:"},{"tipo":"p","c":"a) a legislação;"},{"tipo":"p","c":"b) as Space Rules;"},{"tipo":"p","c":"c) requisitos de segurança;"},{"tipo":"p","c":"d) eventuais autorizações."},{"tipo":"h2","texto":"36. EXPLOSIVOS E SUBSTÂNCIAS PERIGOSAS"},{"tipo":"p","c":"É proibida a utilização não autorizada de:"},{"tipo":"p","c":"a) explosivos;"},{"tipo":"p","c":"b) materiais perigosos;"},{"tipo":"p","c":"c) substâncias tóxicas;"},{"tipo":"p","c":"d) produtos sujeitos a controlo especial."},{"tipo":"h2","texto":"37. DROGAS ILÍCITAS"},{"tipo":"p","c":"A Venue1Hub não poderá ser utilizada para produção, distribuição ou outras atividades ilícitas relacionadas com drogas."},{"tipo":"h2","texto":"38. ÁLCOOL"},{"tipo":"p","c":"O consumo ou fornecimento de álcool deverá respeitar:"},{"tipo":"p","c":"a) a legislação;"},{"tipo":"p","c":"b) idade mínima;"},{"tipo":"p","c":"c) Space Rules;"},{"tipo":"p","c":"d) licenças necessárias."},{"tipo":"h2","texto":"39. INCÊNDIO E PIROTECNIA"},{"tipo":"p","c":"Chama aberta, efeitos de fogo ou pirotecnia só poderão ser utilizados quando:"},{"tipo":"p","c":"a) legalmente permitidos;"},{"tipo":"p","c":"b) autorizados pelo Host;"},{"tipo":"p","c":"c) compatíveis com o Espaço;"},{"tipo":"p","c":"d) cumpram os requisitos de segurança."},{"tipo":"h2","texto":"40. RUÍDO"},{"tipo":"p","c":"Os utilizadores deverão respeitar limites de ruído e os direitos de terceiros."},{"tipo":"h2","texto":"41. COMPORTAMENTO PERTURBADOR"},{"tipo":"p","c":"A Venue1Hub poderá intervir quando o comportamento associado a uma Reserva cause risco ou perturbação grave."},{"tipo":"h2","texto":"42. DANOS"},{"tipo":"p","c":"Danos intencionais ou gravemente negligentes poderão originar:"},{"tipo":"p","c":"a) claim;"},{"tipo":"p","c":"b) cobrança;"},{"tipo":"p","c":"c) suspensão;"},{"tipo":"p","c":"d) outras consequências aplicáveis."},{"tipo":"h2","texto":"43. DESGASTE NORMAL"},{"tipo":"p","c":"Desgaste normal não deverá ser tratado da mesma forma que dano."},{"tipo":"h2","texto":"44. RESPONSABILIDADE POR CONVIDADOS"},{"tipo":"p","c":"O Cliente responsável pela Reserva deverá tomar medidas razoáveis para que os seus convidados e participantes respeitem as regras aplicáveis."},{"tipo":"h2","texto":"45. RESPONSABILIDADE POR COLABORADORES"},{"tipo":"p","c":"Hosts e Prestadores são responsáveis pelas pessoas que utilizem na execução das respetivas atividades, nos termos aplicáveis."},{"tipo":"h2","texto":"46. FRAUDE"},{"tipo":"p","c":"A Venue1Hub poderá utilizar mecanismos de prevenção e deteção de fraude."},{"tipo":"h2","texto":"47. EXEMPLOS DE FRAUDE"},{"tipo":"p","c":"Poderão incluir:"},{"tipo":"p","c":"a) identidade falsa;"},{"tipo":"p","c":"b) documentação falsa;"},{"tipo":"p","c":"c) método de pagamento não autorizado;"},{"tipo":"p","c":"d) Reserva fictícia;"},{"tipo":"p","c":"e) review falsa;"},{"tipo":"p","c":"f) claim fraudulento;"},{"tipo":"p","c":"g) refund fraudulento;"},{"tipo":"p","c":"h) chargeback abusivo;"},{"tipo":"p","c":"i) circumvention fraudulenta;"},{"tipo":"p","c":"j) outra tentativa de obter vantagem indevida."},{"tipo":"h2","texto":"48. MONITORIZAÇÃO DE RISCO"},{"tipo":"p","c":"A Venue1Hub poderá utilizar informação técnica e comportamental para identificar atividade potencialmente suspeita."},{"tipo":"h2","texto":"49. NÃO DIVULGAÇÃO DOS MECANISMOS ANTIFRAUDE"},{"tipo":"p","c":"Para proteger a eficácia dos sistemas de segurança, a Venue1Hub não é obrigada a divulgar:"},{"tipo":"p","c":"a) regras antifraude internas;"},{"tipo":"p","c":"b) thresholds;"},{"tipo":"p","c":"c) modelos de risco;"},{"tipo":"p","c":"d) sinais específicos;"},{"tipo":"p","c":"e) parâmetros de deteção;"},{"tipo":"p","c":"f) outros mecanismos cuja divulgação facilite evasão."},{"tipo":"h2","texto":"50. STRIPE E SEGURANÇA DE PAGAMENTOS"},{"tipo":"p","c":"A infraestrutura Stripe integrada poderá ser utilizada para apoiar:"},{"tipo":"p","c":"a) autenticação;"},{"tipo":"p","c":"b) prevenção de fraude;"},{"tipo":"p","c":"c) segurança dos pagamentos;"},{"tipo":"p","c":"d) disputes;"},{"tipo":"p","c":"e) chargebacks;"},{"tipo":"p","c":"f) outros controlos financeiros."},{"tipo":"h2","texto":"51. PAGAMENTOS FORA DA PLATAFORMA"},{"tipo":"p","c":"Pedidos para realizar fora da Venue1Hub pagamentos que deveriam ocorrer na Plataforma poderão constituir risco de segurança e/ou circumvention."},{"tipo":"h2","texto":"52. DADOS DE CARTÃO"},{"tipo":"p","c":"Os utilizadores não deverão fornecer dados completos de cartões através de:"},{"tipo":"p","c":"a) mensagens;"},{"tipo":"p","c":"b) email;"},{"tipo":"p","c":"c) telefone;"},{"tipo":"p","c":"d) anexos;"},{"tipo":"p","c":"e) outros canais inadequados."},{"tipo":"h2","texto":"53. PHISHING"},{"tipo":"p","c":"É proibido tentar obter fraudulentamente:"},{"tipo":"p","c":"a) passwords;"},{"tipo":"p","c":"b) credenciais;"},{"tipo":"p","c":"c) dados financeiros;"},{"tipo":"p","c":"d) códigos de autenticação;"},{"tipo":"p","c":"e) informação pessoal."},{"tipo":"h2","texto":"54. LINKS SUSPEITOS"},{"tipo":"p","c":"Os utilizadores deverão evitar introduzir credenciais ou dados financeiros em links suspeitos recebidos através da Plataforma."},{"tipo":"h2","texto":"55. IMPERSONAÇÃO"},{"tipo":"p","c":"É proibido fazer-se passar por:"},{"tipo":"p","c":"a) outro utilizador;"},{"tipo":"p","c":"b) Host;"},{"tipo":"p","c":"c) Cliente;"},{"tipo":"p","c":"d) funcionário Venue1Hub;"},{"tipo":"p","c":"e) entidade pública;"},{"tipo":"p","c":"f) outra organização."},{"tipo":"h2","texto":"56. CONTAS COMPROMETIDAS"},{"tipo":"p","c":"Quando existam indícios de comprometimento de Conta, a Venue1Hub poderá aplicar medidas temporárias de segurança."},{"tipo":"h2","texto":"57. RESET E REVERIFICAÇÃO"},{"tipo":"p","c":"Essas medidas poderão incluir:"},{"tipo":"p","c":"a) logout;"},{"tipo":"p","c":"b) reset de password;"},{"tipo":"p","c":"c) nova autenticação;"},{"tipo":"p","c":"d) reverificação;"},{"tipo":"p","c":"e) limitação temporária."},{"tipo":"h2","texto":"58. SEGURANÇA DAS CREDENCIAIS"},{"tipo":"p","c":"Os utilizadores deverão proteger as suas credenciais e não partilhá-las de forma indevida."},{"tipo":"h2","texto":"59. AUTENTICAÇÃO"},{"tipo":"p","c":"A Venue1Hub poderá implementar mecanismos adicionais de autenticação quando necessário."},{"tipo":"h2","texto":"60. CIBERSEGURANÇA"},{"tipo":"p","c":"É proibido:"},{"tipo":"p","c":"a) tentar obter acesso não autorizado;"},{"tipo":"p","c":"b) explorar vulnerabilidades;"},{"tipo":"p","c":"c) introduzir malware;"},{"tipo":"p","c":"d) atacar sistemas;"},{"tipo":"p","c":"e) interferir com a disponibilidade da Plataforma."},{"tipo":"h2","texto":"61. RESPONSIBLE DISCLOSURE"},{"tipo":"p","c":"Quando a Venue1Hub venha a disponibilizar mecanismo específico para reporte de vulnerabilidades, investigadores deverão utilizar esse canal de boa-fé."},{"tipo":"h2","texto":"62. NÃO EXPLORAÇÃO DE VULNERABILIDADES"},{"tipo":"p","c":"A identificação de uma potencial vulnerabilidade não autoriza:"},{"tipo":"p","c":"a) acesso indevido a dados;"},{"tipo":"p","c":"b) exploração;"},{"tipo":"p","c":"c) destruição;"},{"tipo":"p","c":"d) publicação de dados pessoais;"},{"tipo":"p","c":"e) extorsão."},{"tipo":"h2","texto":"63. SEGURANÇA DOS DADOS"},{"tipo":"p","c":"A Venue1Hub procura utilizar medidas técnicas e organizativas destinadas a proteger os dados sob o seu controlo."},{"tipo":"p","c":"O Plano de Negócios prevê expressamente encriptação, controlo de acessos, monitorização, backup e recuperação como elementos da estratégia de segurança."},{"tipo":"h2","texto":"64. ACESSOS INTERNOS"},{"tipo":"p","c":"O acesso interno a informação deverá ser limitado de acordo com necessidade e função."},{"tipo":"h2","texto":"65. MONITORIZAÇÃO DE ATIVIDADE SUSPEITA"},{"tipo":"p","c":"Poderão ser utilizados mecanismos destinados a detetar:"},{"tipo":"p","c":"a) fraude;"},{"tipo":"p","c":"b) acessos anómalos;"},{"tipo":"p","c":"c) abuso;"},{"tipo":"p","c":"d) comportamento automatizado;"},{"tipo":"p","c":"e) outros riscos."},{"tipo":"h2","texto":"66. BACKUPS"},{"tipo":"p","c":"A Venue1Hub poderá manter mecanismos de backup adequados à continuidade operacional."},{"tipo":"h2","texto":"67. CONTINUIDADE DE NEGÓCIO"},{"tipo":"p","c":"A empresa deverá manter processos internos destinados a responder a falhas operacionais ou tecnológicas relevantes."},{"tipo":"h2","texto":"68. INCIDENTES DE SEGURANÇA DE DADOS"},{"tipo":"p","c":"Incidentes envolvendo dados pessoais serão tratados de acordo com os procedimentos de segurança e privacidade aplicáveis."},{"tipo":"h2","texto":"69. DATA BREACH"},{"tipo":"p","c":"Quando um incidente constitua uma violação de dados pessoais, aplicar-se-ão as obrigações previstas pela legislação de proteção de dados."},{"tipo":"h2","texto":"70. INCIDENTES FÍSICOS"},{"tipo":"p","c":"Um incidente físico poderá incluir, entre outros:"},{"tipo":"p","c":"a) lesão;"},{"tipo":"p","c":"b) agressão;"},{"tipo":"p","c":"c) ameaça;"},{"tipo":"p","c":"d) incêndio;"},{"tipo":"p","c":"e) dano grave;"},{"tipo":"p","c":"f) situação perigosa;"},{"tipo":"p","c":"g) emergência médica."},{"tipo":"h2","texto":"71. INCIDENTES FINANCEIROS"},{"tipo":"p","c":"Poderão incluir:"},{"tipo":"p","c":"a) fraude;"},{"tipo":"p","c":"b) pagamento não autorizado;"},{"tipo":"p","c":"c) chargeback suspeito;"},{"tipo":"p","c":"d) payout irregular;"},{"tipo":"p","c":"e) manipulação da transação."},{"tipo":"h2","texto":"72. INCIDENTES DE CONTEÚDO"},{"tipo":"p","c":"Poderão incluir:"},{"tipo":"p","c":"a) conteúdo ilegal;"},{"tipo":"p","c":"b) ameaças;"},{"tipo":"p","c":"c) exploração;"},{"tipo":"p","c":"d) phishing;"},{"tipo":"p","c":"e) impersonação;"},{"tipo":"p","c":"f) publicação indevida de dados."},{"tipo":"h2","texto":"73. INCIDENTES DE IDENTIDADE"},{"tipo":"p","c":"Poderão incluir:"},{"tipo":"p","c":"a) documentos falsos;"},{"tipo":"p","c":"b) identidade roubada;"},{"tipo":"p","c":"c) empresa fictícia;"},{"tipo":"p","c":"d) representante não autorizado."},{"tipo":"h2","texto":"74. COMUNICAR UM INCIDENTE"},{"tipo":"p","c":"Utilizadores poderão comunicar preocupações ou incidentes através:"},{"tipo":"p","c":"a) da área da Reserva;"},{"tipo":"p","c":"b) de mecanismos de denúncia;"},{"tipo":"p","c":"c) do Resolution Centre;"},{"tipo":"p","c":"d) do Help Centre;"},{"tipo":"p","c":[{"t":"e) de "},{"t":"mail@venue1hub.com","b":true},{"t":";"}]},{"tipo":"p","c":"f) de outros canais disponibilizados."},{"tipo":"h2","texto":"75. ESCOLHER O CANAL CORRETO"},{"tipo":"p","c":"Sempre que possível:"},{"tipo":"p","c":[{"t":"Emergência física imediata\n","b":true},{"t":"→ serviços de emergência."}]},{"tipo":"p","c":[{"t":"Conteúdo potencialmente ilegal\n","b":true},{"t":"→ Notice & Action."}]},{"tipo":"p","c":[{"t":"Problema da Reserva / refund / dano\n","b":true},{"t":"→ Resolution Centre."}]},{"tipo":"p","c":[{"t":"Fraude / segurança / comportamento perigoso\n","b":true},{"t":"→ Trust & Safety."}]},{"tipo":"p","c":[{"t":"Problema de dados pessoais\n","b":true},{"t":"→ canais de privacidade."}]},{"tipo":"h2","texto":"76. INFORMAÇÃO DO INCIDENTE"},{"tipo":"p","c":"Uma comunicação deverá, sempre que possível, incluir:"},{"tipo":"p","c":"a) Booking ID;"},{"tipo":"p","c":"b) User ID ou identificação da contraparte;"},{"tipo":"p","c":"c) Listing;"},{"tipo":"p","c":"d) data;"},{"tipo":"p","c":"e) hora;"},{"tipo":"p","c":"f) localização;"},{"tipo":"p","c":"g) descrição;"},{"tipo":"p","c":"h) pessoas envolvidas;"},{"tipo":"p","c":"i) medidas já adotadas;"},{"tipo":"p","c":"j) documentação disponível."},{"tipo":"h2","texto":"77. EVIDÊNCIA"},{"tipo":"p","c":"Poderá ser útil fornecer:"},{"tipo":"p","c":"a) fotografias;"},{"tipo":"p","c":"b) vídeos;"},{"tipo":"p","c":"c) mensagens;"},{"tipo":"p","c":"d) documentos;"},{"tipo":"p","c":"e) relatórios;"},{"tipo":"p","c":"f) recibos;"},{"tipo":"p","c":"g) outras provas relevantes."},{"tipo":"h2","texto":"78. NÃO SE COLOCAR EM RISCO PARA RECOLHER PROVA"},{"tipo":"p","c":"Nenhum utilizador deverá colocar-se em perigo para recolher evidência."},{"tipo":"p","c":"A segurança física tem prioridade."},{"tipo":"h2","texto":"79. CASE ID"},{"tipo":"p","c":"Incidentes relevantes poderão receber identificador próprio."},{"tipo":"p","c":"Exemplo:"},{"tipo":"p","c":[{"t":"TS-V1H-[ANO]-[NÚMERO]","b":true}]},{"tipo":"h2","texto":"80. TRIAGEM"},{"tipo":"p","c":"Após receber um incidente, a Venue1Hub poderá realizar uma triagem para determinar:"},{"tipo":"p","c":"a) gravidade;"},{"tipo":"p","c":"b) urgência;"},{"tipo":"p","c":"c) tipo de risco;"},{"tipo":"p","c":"d) equipa responsável;"},{"tipo":"p","c":"e) necessidade de medida imediata;"},{"tipo":"p","c":"f) necessidade de documentação adicional."},{"tipo":"h2","texto":"81. CLASSIFICAÇÃO DE RISCO"},{"tipo":"p","c":"A Venue1Hub poderá classificar internamente incidentes por nível de risco."},{"tipo":"h2","texto":"82. EXEMPLO DE NÍVEIS INTERNOS"},{"tipo":"p","c":"Uma estrutura possível é:"},{"tipo":"p","c":[{"t":"Nível 1 — Baixo\n","b":true},{"t":"Questão limitada sem risco imediato."}]},{"tipo":"p","c":[{"t":"Nível 2 — Moderado\n","b":true},{"t":"Risco relevante ou incumprimento que exige intervenção."}]},{"tipo":"p","c":[{"t":"Nível 3 — Elevado\n","b":true},{"t":"Fraude, ameaça, risco físico relevante ou comportamento grave."}]},{"tipo":"p","c":[{"t":"Nível 4 — Crítico\n","b":true},{"t":"Risco imediato para pessoas, exploração, violência grave, fraude crítica ou incidente grave de segurança."}]},{"tipo":"p","c":"Esta matriz poderá ser ajustada internamente pela Venue1Hub."},{"tipo":"h2","texto":"83. PRIORIDADE"},{"tipo":"p","c":"Incidentes de risco físico ou segurança imediata poderão receber prioridade sobre questões comerciais ordinárias."},{"tipo":"h2","texto":"84. INVESTIGAÇÃO"},{"tipo":"p","c":"A Venue1Hub poderá analisar informação legitimamente disponível relacionada com o incidente."},{"tipo":"h2","texto":"85. FONTES DA INVESTIGAÇÃO"},{"tipo":"p","c":"Poderão ser considerados:"},{"tipo":"p","c":"a) dados da Conta;"},{"tipo":"p","c":"b) Reservas;"},{"tipo":"p","c":"c) Listings;"},{"tipo":"p","c":"d) pagamentos;"},{"tipo":"p","c":"e) mensagens através da Plataforma, quando legalmente permitido;"},{"tipo":"p","c":"f) reviews;"},{"tipo":"p","c":"g) denúncias;"},{"tipo":"p","c":"h) documentos;"},{"tipo":"p","c":"i) informação técnica;"},{"tipo":"p","c":"j) respostas dos envolvidos."},{"tipo":"h2","texto":"86. PEDIDO DE ESCLARECIMENTOS"},{"tipo":"p","c":"A Venue1Hub poderá solicitar informação adicional às partes."},{"tipo":"h2","texto":"87. COOPERAÇÃO"},{"tipo":"p","c":"Utilizadores deverão cooperar razoavelmente em investigações legítimas relacionadas com segurança, fraude ou risco."},{"tipo":"h2","texto":"88. DIREITO DE RESPOSTA"},{"tipo":"p","c":"Quando adequado e seguro, a parte afetada poderá ter oportunidade de explicar a sua posição."},{"tipo":"h2","texto":"89. EXCEÇÕES AO CONTRADITÓRIO PRÉVIO"},{"tipo":"p","c":"Uma medida poderá ser aplicada antes de ouvir a parte quando exista:"},{"tipo":"p","c":"a) risco imediato;"},{"tipo":"p","c":"b) fraude;"},{"tipo":"p","c":"c) ameaça;"},{"tipo":"p","c":"d) obrigação legal;"},{"tipo":"p","c":"e) risco de destruição de evidência;"},{"tipo":"p","c":"f) outra necessidade urgente."},{"tipo":"h2","texto":"90. MEDIDAS PROVISÓRIAS"},{"tipo":"p","c":"A Venue1Hub poderá adotar medidas temporárias enquanto analisa a situação."},{"tipo":"h2","texto":"91. EXEMPLOS DE MEDIDAS PROVISÓRIAS"},{"tipo":"p","c":"Estas poderão incluir:"},{"tipo":"p","c":"a) pausar Listing;"},{"tipo":"p","c":"b) bloquear novas Reservas;"},{"tipo":"p","c":"c) restringir Conta;"},{"tipo":"p","c":"d) suspender pagamentos ou payouts na medida permitida pela arquitetura aplicável;"},{"tipo":"p","c":"e) limitar mensagens;"},{"tipo":"p","c":"f) impedir contacto entre utilizadores através da Plataforma;"},{"tipo":"p","c":"g) preservar evidência;"},{"tipo":"p","c":"h) outras medidas proporcionais."},{"tipo":"h2","texto":"92. CANCELAMENTO DE RESERVA POR SEGURANÇA"},{"tipo":"p","c":"Quando exista risco significativo, uma Reserva poderá ser cancelada."},{"tipo":"h2","texto":"93. SEGURANÇA SOBRE POLÍTICA DE CANCELAMENTO"},{"tipo":"p","c":"Em situações graves de segurança, a proteção de pessoas poderá justificar tratamento diferente das regras comerciais ordinárias de cancelamento."},{"tipo":"h2","texto":"94. RELOCALIZAÇÃO OU ALTERNATIVA"},{"tipo":"p","c":"Quando adequado, a Venue1Hub poderá apoiar a procura de alternativa, sem garantia de disponibilidade."},{"tipo":"h2","texto":"95. REFUNDS"},{"tipo":"p","c":"A existência de incidente não determina automaticamente refund."},{"tipo":"p","c":"A solução financeira dependerá:"},{"tipo":"p","c":"a) dos factos;"},{"tipo":"p","c":"b) da responsabilidade;"},{"tipo":"p","c":"c) da política aplicável;"},{"tipo":"p","c":"d) do serviço prestado;"},{"tipo":"p","c":"e) da legislação."},{"tipo":"h2","texto":"96. PAYOUTS"},{"tipo":"p","c":"Payouts poderão ser temporariamente afetados quando necessário para:"},{"tipo":"p","c":"a) fraude;"},{"tipo":"p","c":"b) refund;"},{"tipo":"p","c":"c) chargeback;"},{"tipo":"p","c":"d) investigação;"},{"tipo":"p","c":"e) obrigação legal,"},{"tipo":"p","c":"nos termos dos Termos de Pagamento e arquitetura Stripe."},{"tipo":"h2","texto":"97. STRIPE E RISCO FINANCEIRO"},{"tipo":"p","c":"A Stripe poderá igualmente aplicar os seus próprios processos de:"},{"tipo":"p","c":"a) verificação;"},{"tipo":"p","c":"b) fraude;"},{"tipo":"p","c":"c) risco;"},{"tipo":"p","c":"d) disputes;"},{"tipo":"p","c":"e) restrições de pagamento."},{"tipo":"h2","texto":"98. NÃO PROMESSA DE RESULTADO"},{"tipo":"p","c":"A abertura de uma investigação não significa que a Venue1Hub irá necessariamente:"},{"tipo":"p","c":"a) suspender alguém;"},{"tipo":"p","c":"b) emitir refund;"},{"tipo":"p","c":"c) determinar culpa;"},{"tipo":"p","c":"d) pagar indemnização."},{"tipo":"h2","texto":"99. RESULTADOS POSSÍVEIS"},{"tipo":"p","c":"Um caso poderá resultar em:"},{"tipo":"p","c":"a) ausência de medida;"},{"tipo":"p","c":"b) aviso;"},{"tipo":"p","c":"c) pedido de correção;"},{"tipo":"p","c":"d) remoção de conteúdo;"},{"tipo":"p","c":"e) suspensão de Listing;"},{"tipo":"p","c":"f) cancelamento de Reserva;"},{"tipo":"p","c":"g) restrição de funcionalidades;"},{"tipo":"p","c":"h) reverificação;"},{"tipo":"p","c":"i) suspensão da Conta;"},{"tipo":"p","c":"j) encerramento;"},{"tipo":"p","c":"k) encaminhamento para outro procedimento."},{"tipo":"h2","texto":"100. PROPORCIONALIDADE"},{"tipo":"p","c":"A Venue1Hub poderá considerar:"},{"tipo":"p","c":"a) gravidade;"},{"tipo":"p","c":"b) risco;"},{"tipo":"p","c":"c) frequência;"},{"tipo":"p","c":"d) intenção;"},{"tipo":"p","c":"e) impacto;"},{"tipo":"p","c":"f) histórico;"},{"tipo":"p","c":"g) colaboração;"},{"tipo":"p","c":"h) proteção das partes."},{"tipo":"h2","texto":"101. REINCIDÊNCIA"},{"tipo":"p","c":"Comportamentos repetidos poderão justificar medidas progressivamente mais restritivas."},{"tipo":"h2","texto":"102. VIOLAÇÕES GRAVES ÚNICAS"},{"tipo":"p","c":"Uma única ocorrência poderá justificar suspensão imediata quando suficientemente grave."},{"tipo":"h2","texto":"103. CONTEÚDO ILEGAL"},{"tipo":"p","c":"Conteúdo potencialmente ilegal poderá ser tratado através do Procedimento Notice & Action."},{"tipo":"h2","texto":"104. CONTEÚDO CONTRÁRIO ÀS POLÍTICAS"},{"tipo":"p","c":"Conteúdo que não seja necessariamente ilegal poderá ser tratado ao abrigo da Política de Conteúdos."},{"tipo":"h2","texto":"105. SUSPENSÃO"},{"tipo":"p","c":"Medidas sobre Contas serão regidas também pela Política de Suspensão e Encerramento de Contas."},{"tipo":"h2","texto":"106. DANOS"},{"tipo":"p","c":"Danos serão tratados através da Política de Danos, Cauções e Reclamações quando aplicável."},{"tipo":"h2","texto":"107. CONFLITOS TRANSACIONAIS"},{"tipo":"p","c":"Conflitos entre Host e Cliente poderão ser encaminhados para o Resolution Centre."},{"tipo":"h2","texto":"108. REVIEWS"},{"tipo":"p","c":"Problemas relativos a avaliações serão tratados pela Política de Avaliações e Reviews."},{"tipo":"h2","texto":"109. CIRCUMVENTION"},{"tipo":"p","c":"Desvio de transações será analisado segundo a Política Anti-Circumvention."},{"tipo":"h2","texto":"110. PROPRIEDADE INTELECTUAL"},{"tipo":"p","c":"Denúncias de propriedade intelectual poderão ser encaminhadas para o procedimento respetivo."},{"tipo":"h2","texto":"111. SEGURANÇA DO HOST"},{"tipo":"p","c":"Hosts deverão:"},{"tipo":"p","c":"a) manter informação correta;"},{"tipo":"p","c":"b) respeitar requisitos legais;"},{"tipo":"p","c":"c) comunicar riscos conhecidos;"},{"tipo":"p","c":"d) assegurar condições adequadas de utilização;"},{"tipo":"p","c":"e) respeitar Reservas confirmadas;"},{"tipo":"p","c":"f) agir de boa-fé."},{"tipo":"h2","texto":"112. SEGURANÇA DO CLIENTE"},{"tipo":"p","c":"Clientes deverão:"},{"tipo":"p","c":"a) respeitar Space Rules;"},{"tipo":"p","c":"b) utilizar o Espaço apenas para finalidade permitida;"},{"tipo":"p","c":"c) respeitar capacidade;"},{"tipo":"p","c":"d) agir de forma segura;"},{"tipo":"p","c":"e) controlar razoavelmente os participantes;"},{"tipo":"p","c":"f) comunicar incidentes relevantes."},{"tipo":"h2","texto":"113. SEGURANÇA DOS PRESTADORES"},{"tipo":"p","c":"Prestadores deverão:"},{"tipo":"p","c":"a) possuir habilitações necessárias;"},{"tipo":"p","c":"b) operar de forma profissional;"},{"tipo":"p","c":"c) cumprir normas de segurança;"},{"tipo":"p","c":"d) respeitar o Espaço;"},{"tipo":"p","c":"e) utilizar equipamento adequado;"},{"tipo":"p","c":"f) cumprir a legislação."},{"tipo":"h2","texto":"114. PARTICIPANTES"},{"tipo":"p","c":"O responsável pela Reserva deverá tomar medidas razoáveis para informar os participantes das regras relevantes."},{"tipo":"h2","texto":"115. ACESSO AO ESPAÇO"},{"tipo":"p","c":"Hosts deverão utilizar mecanismos razoáveis e adequados para gestão de:"},{"tipo":"p","c":"a) chaves;"},{"tipo":"p","c":"b) códigos;"},{"tipo":"p","c":"c) acessos;"},{"tipo":"p","c":"d) áreas restritas."},{"tipo":"h2","texto":"116. CÓDIGOS DE ACESSO"},{"tipo":"p","c":"Códigos não deverão ser partilhados publicamente ou mantidos ativos além do necessário quando o sistema permita gestão temporária."},{"tipo":"h2","texto":"117. CHAVES"},{"tipo":"p","c":"Clientes não deverão copiar ou conservar chaves sem autorização."},{"tipo":"h2","texto":"118. ACESSO APÓS RESERVA"},{"tipo":"p","c":"O Cliente não deverá utilizar credenciais de acesso após o período autorizado."},{"tipo":"h2","texto":"119. VISITANTES NÃO AUTORIZADOS"},{"tipo":"p","c":"Não é permitido permitir deliberadamente acesso a pessoas não autorizadas quando isso viole as condições da Reserva ou regras de segurança."},{"tipo":"h2","texto":"120. CÂMARAS E VIGILÂNCIA"},{"tipo":"p","c":"Sistemas de vigilância deverão respeitar a legislação aplicável."},{"tipo":"h2","texto":"121. INFORMAÇÃO SOBRE VIGILÂNCIA"},{"tipo":"p","c":"Hosts deverão prestar a informação legalmente exigida sobre sistemas relevantes existentes no Espaço."},{"tipo":"h2","texto":"122. ÁREAS PRIVADAS"},{"tipo":"p","c":"Não são permitidas câmaras ou dispositivos de gravação em áreas onde sejam legalmente proibidos ou incompatíveis com expectativas legítimas de privacidade."},{"tipo":"h2","texto":"123. DISPOSITIVOS OCULTOS"},{"tipo":"p","c":"A utilização ilegal de dispositivos de vigilância ocultos poderá resultar em medidas imediatas."},{"tipo":"h2","texto":"124. PRIVACIDADE DOS PARTICIPANTES"},{"tipo":"p","c":"Hosts, Clientes e Prestadores deverão respeitar os direitos de privacidade das pessoas presentes."},{"tipo":"h2","texto":"125. GRAVAÇÕES"},{"tipo":"p","c":"Fotografia ou vídeo deverão respeitar:"},{"tipo":"p","c":"a) legislação;"},{"tipo":"p","c":"b) direitos de imagem;"},{"tipo":"p","c":"c) consentimentos necessários;"},{"tipo":"p","c":"d) Space Rules."},{"tipo":"h2","texto":"126. DADOS PESSOAIS"},{"tipo":"p","c":"Não é permitido utilizar dados obtidos através da Venue1Hub para:"},{"tipo":"p","c":"a) assédio;"},{"tipo":"p","c":"b) profiling abusivo;"},{"tipo":"p","c":"c) venda não autorizada;"},{"tipo":"p","c":"d) marketing não autorizado;"},{"tipo":"p","c":"e) outros fins incompatíveis."},{"tipo":"h2","texto":"127. TRUST & SAFETY E PRIVACIDADE"},{"tipo":"p","c":"Os processos de segurança deverão ser realizados em conformidade com a Política de Privacidade e as obrigações de proteção de dados aplicáveis."},{"tipo":"h2","texto":"128. MINIMIZAÇÃO"},{"tipo":"p","c":"A Venue1Hub deverá procurar utilizar apenas os dados necessários à análise de segurança relevante."},{"tipo":"h2","texto":"129. CONSERVAÇÃO"},{"tipo":"p","c":"Dados relacionados com incidentes poderão ser conservados pelo período necessário para:"},{"tipo":"p","c":"a) investigação;"},{"tipo":"p","c":"b) fraude;"},{"tipo":"p","c":"c) defesa de direitos;"},{"tipo":"p","c":"d) litígios;"},{"tipo":"p","c":"e) cumprimento legal;"},{"tipo":"p","c":"f) segurança futura."},{"tipo":"h2","texto":"130. LEGAL HOLD"},{"tipo":"p","c":"Informação poderá ser preservada durante período adicional quando exista litígio, investigação ou outra necessidade legal legítima."},{"tipo":"h2","texto":"131. ACESSO INTERNO RESTRITO"},{"tipo":"p","c":"Casos de Trust & Safety poderão conter informação sensível e deverão ter acesso interno limitado de acordo com necessidade."},{"tipo":"h2","texto":"132. CONFIDENCIALIDADE"},{"tipo":"p","c":"A Venue1Hub poderá limitar detalhes de investigações para proteger:"},{"tipo":"p","c":"a) vítimas;"},{"tipo":"p","c":"b) denunciantes;"},{"tipo":"p","c":"c) testemunhas;"},{"tipo":"p","c":"d) terceiros;"},{"tipo":"p","c":"e) mecanismos de segurança."},{"tipo":"h2","texto":"133. NÃO RETALIAÇÃO"},{"tipo":"p","c":"É proibido retaliar contra utilizador apenas por ter apresentado, de boa-fé:"},{"tipo":"p","c":"a) denúncia;"},{"tipo":"p","c":"b) reclamação;"},{"tipo":"p","c":"c) pedido de ajuda;"},{"tipo":"p","c":"d) informação de segurança."},{"tipo":"h2","texto":"134. DENÚNCIAS FALSAS"},{"tipo":"p","c":"A apresentação deliberada de informação falsa para prejudicar outra pessoa poderá originar medidas."},{"tipo":"h2","texto":"135. COOPERAÇÃO COM AUTORIDADES"},{"tipo":"p","c":"A Venue1Hub poderá cooperar com autoridades competentes quando legalmente exigido ou permitido."},{"tipo":"h2","texto":"136. ORDENS JUDICIAIS OU ADMINISTRATIVAS"},{"tipo":"p","c":"A Venue1Hub poderá responder a ordens juridicamente válidas relativas a:"},{"tipo":"p","c":"a) dados;"},{"tipo":"p","c":"b) Contas;"},{"tipo":"p","c":"c) conteúdos;"},{"tipo":"p","c":"d) pagamentos;"},{"tipo":"p","c":"e) outras informações."},{"tipo":"h2","texto":"137. RISCO DE CRIME"},{"tipo":"p","c":"Quando existam fundamentos adequados e obrigação ou autorização legal, certos incidentes poderão ser comunicados às autoridades."},{"tipo":"h2","texto":"138. EXPLORAÇÃO E MENORES"},{"tipo":"p","c":"Casos de exploração ou abuso de menores poderão ser tratados com prioridade máxima e comunicados conforme exigido pela lei."},{"tipo":"h2","texto":"139. TRANSPARÊNCIA"},{"tipo":"p","c":"A Venue1Hub poderá publicar informação agregada sobre:"},{"tipo":"p","c":"a) denúncias;"},{"tipo":"p","c":"b) moderação;"},{"tipo":"p","c":"c) incidentes;"},{"tipo":"p","c":"d) medidas,"},{"tipo":"p","c":"quando legalmente aplicável ou adequado."},{"tipo":"h2","texto":"140. NÃO IDENTIFICAÇÃO INDEVIDA"},{"tipo":"p","c":"Relatórios públicos não deverão expor indevidamente dados pessoais ou informação confidencial."},{"tipo":"h2","texto":"141. TRUST & SAFETY CENTRE"},{"tipo":"p","c":"A Venue1Hub poderá disponibilizar no site uma área pública dedicada a:"},{"tipo":"p","c":"a) segurança;"},{"tipo":"p","c":"b) prevenção de fraude;"},{"tipo":"p","c":"c) comportamento;"},{"tipo":"p","c":"d) reporting;"},{"tipo":"p","c":"e) emergências;"},{"tipo":"p","c":"f) FAQs;"},{"tipo":"p","c":"g) recursos de ajuda."},{"tipo":"h2","texto":"142. LEGAL & TRUST CENTRE"},{"tipo":"p","c":"A Trust & Safety Policy deverá estar integrada no Legal & Trust Centre da Venue1Hub."},{"tipo":"p","c":"O guia jurídico interno recomenda precisamente que Trust & Safety seja uma das entradas centrais do site público, em vez de dispersar toda a arquitetura de compliance em dezenas de links desorganizados."},{"tipo":"h2","texto":"143. RECURSOS PARA HOSTS"},{"tipo":"p","c":"A Venue1Hub poderá disponibilizar orientações sobre:"},{"tipo":"p","c":"a) preparação segura do Espaço;"},{"tipo":"p","c":"b) acesso;"},{"tipo":"p","c":"c) emergências;"},{"tipo":"p","c":"d) capacidade;"},{"tipo":"p","c":"e) incidentes;"},{"tipo":"p","c":"f) prevenção de fraude."},{"tipo":"h2","texto":"144. RECURSOS PARA CLIENTES"},{"tipo":"p","c":"A Venue1Hub poderá disponibilizar informação sobre:"},{"tipo":"p","c":"a) pagamentos seguros;"},{"tipo":"p","c":"b) identificação de fraude;"},{"tipo":"p","c":"c) utilização segura de Espaços;"},{"tipo":"p","c":"d) emergências;"},{"tipo":"p","c":"e) reporting."},{"tipo":"h2","texto":"145. RECURSOS PARA PRESTADORES"},{"tipo":"p","c":"Prestadores poderão receber informação relacionada com:"},{"tipo":"p","c":"a) segurança no local;"},{"tipo":"p","c":"b) acessos;"},{"tipo":"p","c":"c) proteção de dados;"},{"tipo":"p","c":"d) pagamentos;"},{"tipo":"p","c":"e) incidentes."},{"tipo":"h2","texto":"146. CUSTOMER SUPPORT"},{"tipo":"p","c":"Customer Support poderá atuar como primeiro ponto de contacto para questões de menor risco."},{"tipo":"h2","texto":"147. ESCALONAMENTO"},{"tipo":"p","c":"Casos relevantes deverão poder ser escalados para funções adequadas, incluindo:"},{"tipo":"p","c":"a) Trust & Safety;"},{"tipo":"p","c":"b) Fraud/Risk;"},{"tipo":"p","c":"c) Payments;"},{"tipo":"p","c":"d) Legal;"},{"tipo":"p","c":"e) Privacy;"},{"tipo":"p","c":"f) Management,"},{"tipo":"p","c":"conforme a natureza do caso."},{"tipo":"h2","texto":"148. CASOS CRÍTICOS"},{"tipo":"p","c":"A Venue1Hub deverá manter procedimentos internos separados para incidentes críticos."},{"tipo":"h2","texto":"149. DOCUMENTAÇÃO INTERNA"},{"tipo":"p","c":"Esta Política pública não substitui documentação operacional interna como:"},{"tipo":"p","c":"a) Incident Response Plan;"},{"tipo":"p","c":"b) Fraud & Risk Procedure;"},{"tipo":"p","c":"c) Content Moderation Procedure;"},{"tipo":"p","c":"d) Illegal Content Escalation;"},{"tipo":"p","c":"e) Suspension Procedure;"},{"tipo":"p","c":"f) Data Breach Procedure;"},{"tipo":"p","c":"g) KYC escalation;"},{"tipo":"p","c":"h) sanctions/fraud escalation;"},{"tipo":"p","c":"i) Business Continuity Plan."},{"tipo":"p","c":"O guia interno da Venue1Hub prevê expressamente este Legal Operations Pack."},{"tipo":"h2","texto":"150. NÃO PUBLICAÇÃO DE REGRAS INTERNAS SENSÍVEIS"},{"tipo":"p","c":"Alguns procedimentos e parâmetros de segurança permanecerão internos para evitar que sejam utilizados para:"},{"tipo":"p","c":"a) contornar deteção;"},{"tipo":"p","c":"b) cometer fraude;"},{"tipo":"p","c":"c) explorar vulnerabilidades;"},{"tipo":"p","c":"d) prejudicar investigações."},{"tipo":"h2","texto":"151. CONSISTÊNCIA DAS DECISÕES"},{"tipo":"p","c":"A Venue1Hub deverá procurar aplicar critérios consistentes em casos semelhantes."},{"tipo":"h2","texto":"152. CONTEXTO"},{"tipo":"p","c":"Consistência não significa tratamento mecânico."},{"tipo":"p","c":"O contexto de cada caso continuará a ser relevante."},{"tipo":"h2","texto":"153. REVISÃO HUMANA"},{"tipo":"p","c":"Casos graves ou complexos poderão exigir revisão humana."},{"tipo":"h2","texto":"154. AUTOMAÇÃO"},{"tipo":"p","c":"Ferramentas automatizadas poderão apoiar:"},{"tipo":"p","c":"a) deteção;"},{"tipo":"p","c":"b) triagem;"},{"tipo":"p","c":"c) categorização;"},{"tipo":"p","c":"d) scoring;"},{"tipo":"p","c":"e) identificação de padrões."},{"tipo":"h2","texto":"155. LIMITES DA AUTOMAÇÃO"},{"tipo":"p","c":"Uma indicação automatizada de risco não significa automaticamente que tenha ocorrido violação."},{"tipo":"h2","texto":"156. MEDIDAS DE SEGURANÇA AUTOMÁTICAS"},{"tipo":"p","c":"Em determinados casos, sistemas poderão bloquear temporariamente uma ação para:"},{"tipo":"p","c":"a) evitar fraude;"},{"tipo":"p","c":"b) exigir autenticação;"},{"tipo":"p","c":"c) verificar identidade;"},{"tipo":"p","c":"d) proteger Conta;"},{"tipo":"p","c":"e) impedir transação suspeita."},{"tipo":"h2","texto":"157. REVISÃO DE BLOQUEIOS"},{"tipo":"p","c":"Quando apropriado, bloqueios de segurança poderão ser posteriormente revistos."},{"tipo":"h2","texto":"158. SANÇÕES ECONÓMICAS E RISCO"},{"tipo":"p","c":"A Venue1Hub poderá implementar mecanismos destinados a cumprir sanções ou restrições legalmente aplicáveis."},{"tipo":"h2","texto":"159. BRANQUEAMENTO DE CAPITAIS"},{"tipo":"p","c":"É proibido utilizar a Venue1Hub para branqueamento de capitais ou ocultação da origem de fundos."},{"tipo":"h2","texto":"160. FINANCIAMENTO DE ATIVIDADES ILÍCITAS"},{"tipo":"p","c":"A Plataforma não poderá ser utilizada para financiar atividades proibidas por lei."},{"tipo":"h2","texto":"161. RESPONSABILIDADE DOS UTILIZADORES"},{"tipo":"p","c":"Cada utilizador deverá agir de forma razoável para proteger:"},{"tipo":"p","c":"a) a própria Conta;"},{"tipo":"p","c":"b) os seus pagamentos;"},{"tipo":"p","c":"c) a sua segurança;"},{"tipo":"p","c":"d) os outros participantes;"},{"tipo":"p","c":"e) o Espaço."},{"tipo":"h2","texto":"162. SINAIS DE POSSÍVEL FRAUDE"},{"tipo":"p","c":"Os utilizadores deverão ser prudentes perante:"},{"tipo":"p","c":"a) pedidos de pagamento externo;"},{"tipo":"p","c":"b) pressão para agir rapidamente;"},{"tipo":"p","c":"c) mudança inesperada de dados bancários;"},{"tipo":"p","c":"d) pedidos de password;"},{"tipo":"p","c":"e) links suspeitos;"},{"tipo":"p","c":"f) documentos inconsistentes;"},{"tipo":"p","c":"g) propostas excessivamente discrepantes."},{"tipo":"h2","texto":"163. COMUNICAÇÕES OFICIAIS"},{"tipo":"p","c":"A Venue1Hub nunca deverá solicitar aos utilizadores que enviem passwords completas por email ou mensagem."},{"tipo":"h2","texto":"164. DOMÍNIO E CONTACTOS"},{"tipo":"p","c":"Os utilizadores deverão verificar se comunicações que alegam ser da Venue1Hub são consistentes com os canais oficiais."},{"tipo":"p","c":"O website oficial é:"},{"tipo":"p","c":[{"t":"www.venue1hub.com","href":"http://www.venue1hub.com/"}]},{"tipo":"p","c":"E o endereço de contacto geral é:"},{"tipo":"p","c":[{"t":"mail@venue1hub.com","b":true}]},{"tipo":"h2","texto":"165. NÃO CONFIAR EM CONTACTOS FALSOS"},{"tipo":"p","c":"A Venue1Hub não assume responsabilidade por terceiros que se façam falsamente passar pela Plataforma, sem prejuízo das medidas razoáveis que possa adotar após tomar conhecimento."},{"tipo":"h2","texto":"166. REPORTAR IMPERSONAÇÃO"},{"tipo":"p","c":"Tentativas de impersonação da Venue1Hub deverão ser comunicadas para:"},{"tipo":"p","c":[{"t":"mail@venue1hub.com","b":true}]},{"tipo":"h2","texto":"167. SEGURANÇA DO PAGAMENTO"},{"tipo":"p","c":"O utilizador deverá confirmar que o pagamento está a ser efetuado através do checkout oficial Venue1Hub."},{"tipo":"h2","texto":"168. PAGAMENTO NÃO CONFIRMADO"},{"tipo":"p","c":"O Host não deverá considerar uma Reserva paga apenas com base em:"},{"tipo":"p","c":"a) screenshot;"},{"tipo":"p","c":"b) email externo;"},{"tipo":"p","c":"c) comprovativo não verificado;"},{"tipo":"p","c":"d) mensagem do Cliente."},{"tipo":"p","c":"O estado da transação deverá ser confirmado pelos sistemas oficiais da Plataforma."},{"tipo":"h2","texto":"169. NÃO ACEITAR PROVA FALSA DE PAGAMENTO"},{"tipo":"p","c":"Comprovativos falsificados poderão constituir fraude."},{"tipo":"h2","texto":"170. PROTEÇÃO DOS PAYOUTS"},{"tipo":"p","c":"Hosts e Prestadores deverão atualizar dados bancários apenas através dos mecanismos oficiais disponibilizados."},{"tipo":"h2","texto":"171. ALTERAÇÃO SUSPEITA DE CONTA BANCÁRIA"},{"tipo":"p","c":"A Venue1Hub ou Stripe poderão exigir verificação adicional quando existam alterações relevantes."},{"tipo":"h2","texto":"172. SEGURANÇA EM VISITAS PRÉVIAS"},{"tipo":"p","c":"Quando existam visitas a um Espaço antes da Reserva, as partes deverão adotar cuidados razoáveis."},{"tipo":"h2","texto":"173. VISITA NÃO É RESERVA"},{"tipo":"p","c":"Uma visita técnica ou comercial não atribui automaticamente direito de utilização do Espaço."},{"tipo":"h2","texto":"174. SEGURANÇA DURANTE MONTAGEM"},{"tipo":"p","c":"Clientes e Prestadores deverão seguir as regras do Espaço durante montagem e desmontagem."},{"tipo":"h2","texto":"175. EQUIPAMENTOS PESADOS"},{"tipo":"p","c":"Equipamentos que possam criar risco deverão ser previamente autorizados quando necessário."},{"tipo":"h2","texto":"176. TRABALHOS EM ALTURA OU TÉCNICOS"},{"tipo":"p","c":"Atividades especializadas deverão ser realizadas apenas por pessoas adequadamente qualificadas quando exigido."},{"tipo":"h2","texto":"177. CAPACIDADE DE EVACUAÇÃO"},{"tipo":"p","c":"Eventos deverão respeitar a capacidade segura e as regras aplicáveis."},{"tipo":"h2","texto":"178. PARTICIPANTES VULNERÁVEIS"},{"tipo":"p","c":"Organizadores deverão considerar necessidades específicas de segurança e acessibilidade dos participantes quando relevante."},{"tipo":"h2","texto":"179. ACESSIBILIDADE E SEGURANÇA"},{"tipo":"p","c":"A informação relativa a acessibilidade deverá ser correta e não enganadora."},{"tipo":"h2","texto":"180. ANIMAIS DE ASSISTÊNCIA"},{"tipo":"p","c":"Questões relativas a animais de assistência deverão ser tratadas de acordo com a legislação aplicável."},{"tipo":"h2","texto":"181. SEGURANÇA ALIMENTAR"},{"tipo":"p","c":"Prestadores de catering são responsáveis pelas normas de segurança alimentar aplicáveis."},{"tipo":"h2","texto":"182. ALERGÉNIOS"},{"tipo":"p","c":"Informação sobre alergénios deverá ser fornecida quando legalmente exigido."},{"tipo":"h2","texto":"183. SERVIÇOS REGULADOS"},{"tipo":"p","c":"A prestação de atividade regulada deverá ser realizada apenas por pessoas ou entidades legalmente habilitadas."},{"tipo":"h2","texto":"184. SEGURANÇA PRIVADA"},{"tipo":"p","c":"Prestadores de segurança deverão possuir as autorizações legalmente exigidas."},{"tipo":"h2","texto":"185. ATIVIDADES DE SAÚDE"},{"tipo":"p","c":"Profissionais que utilizem Espaços para atividades de saúde continuam responsáveis pelos requisitos específicos da sua atividade."},{"tipo":"h2","texto":"186. EVENTOS COM MENORES"},{"tipo":"p","c":"Organizadores continuam responsáveis por cumprir as obrigações de supervisão e proteção que lhes sejam aplicáveis."},{"tipo":"h2","texto":"187. ALTERAÇÕES A ESTA POLÍTICA"},{"tipo":"p","c":"A Venue1Hub poderá atualizar esta Política para refletir:"},{"tipo":"p","c":"a) novos riscos;"},{"tipo":"p","c":"b) experiência operacional;"},{"tipo":"p","c":"c) novas funcionalidades;"},{"tipo":"p","c":"d) novos mercados;"},{"tipo":"p","c":"e) alterações legais;"},{"tipo":"p","c":"f) novos mecanismos de verificação;"},{"tipo":"p","c":"g) novas ferramentas antifraude;"},{"tipo":"p","c":"h) evolução das práticas de segurança."},{"tipo":"h2","texto":"188. ALTERAÇÕES MATERIAIS"},{"tipo":"p","c":"Quando adequado, alterações materiais serão comunicadas através dos mecanismos aplicáveis."},{"tipo":"h2","texto":"189. VERSÃO"},{"tipo":"p","c":"A Venue1Hub deverá manter controlo da versão desta Política."},{"tipo":"h2","texto":"190. HISTÓRICO INTERNO"},{"tipo":"p","c":"Internamente deverão ser registados, quando aplicável:"},{"tipo":"p","c":"a) versão;"},{"tipo":"p","c":"b) data;"},{"tipo":"p","c":"c) owner;"},{"tipo":"p","c":"d) aprovação;"},{"tipo":"p","c":"e) alterações;"},{"tipo":"p","c":"f) versão anterior."},{"tipo":"p","c":"O guia jurídico exige versionamento e prova das políticas e decisões relevantes da Plataforma."},{"tipo":"h2","texto":"191. TRUST & SAFETY CASE RECORD"},{"tipo":"p","c":"Para casos relevantes, a Venue1Hub deverá conseguir conservar, conforme aplicável:"},{"tipo":"lista","chave":"6","itens":[{"n":0,"c":"Trust & Safety Case ID;"},{"n":0,"c":"Booking ID;"},{"n":0,"c":"Listing ID;"},{"n":0,"c":"Host ID;"},{"n":0,"c":"Client ID;"},{"n":0,"c":"Provider ID;"},{"n":0,"c":"categoria do incidente;"},{"n":0,"c":"nível de risco;"},{"n":0,"c":"data e hora;"},{"n":0,"c":"localização;"},{"n":0,"c":"descrição;"},{"n":0,"c":"prova;"},{"n":0,"c":"denunciante;"},{"n":0,"c":"utilizadores envolvidos;"},{"n":0,"c":"medidas urgentes;"},{"n":0,"c":"comunicação às partes;"},{"n":0,"c":"investigação;"},{"n":0,"c":"decisão;"},{"n":0,"c":"medida aplicada;"},{"n":0,"c":"pagamentos afetados;"},{"n":0,"c":"Reservas afetadas;"},{"n":0,"c":"eventual comunicação a autoridades;"},{"n":0,"c":"contestação;"},{"n":0,"c":"revisão;"},{"n":0,"c":"data de encerramento."}]},{"tipo":"h2","texto":"192. FLUXO OPERACIONAL RECOMENDADO"},{"tipo":"p","c":[{"t":"INCIDENTE / ALERTA / DENÚNCIA","b":true}]},{"tipo":"p","c":"↓"},{"tipo":"p","c":[{"t":"RISCO IMEDIATO?","b":true}]},{"tipo":"p","c":"↓"},{"tipo":"p","c":[{"t":"SIM → EMERGÊNCIA / MEDIDA DE PROTEÇÃO","b":true}]},{"tipo":"p","c":"↓"},{"tipo":"p","c":[{"t":"CASE ID","b":true}]},{"tipo":"p","c":"↓"},{"tipo":"p","c":[{"t":"TRIAGEM TRUST & SAFETY","b":true}]},{"tipo":"p","c":"↓"},{"tipo":"p","c":[{"t":"CLASSIFICAÇÃO DE RISCO","b":true}]},{"tipo":"p","c":"↓"},{"tipo":"p","c":[{"t":"PRESERVAÇÃO DE EVIDÊNCIA","b":true}]},{"tipo":"p","c":"↓"},{"tipo":"p","c":[{"t":"MEDIDAS PROVISÓRIAS, SE NECESSÁRIAS","b":true}]},{"tipo":"p","c":"↓"},{"tipo":"p","c":[{"t":"INVESTIGAÇÃO","b":true}]},{"tipo":"p","c":"↓"},{"tipo":"p","c":[{"t":"RESPOSTA DAS PARTES, QUANDO ADEQUADO","b":true}]},{"tipo":"p","c":"↓"},{"tipo":"p","c":[{"t":"DECISÃO OPERACIONAL","b":true}]},{"tipo":"p","c":"↓"},{"tipo":"p","c":[{"t":"RESERVA / LISTING / CONTA / PAGAMENTO","b":true}]},{"tipo":"p","c":"↓"},{"tipo":"p","c":[{"t":"COMUNICAÇÃO DA DECISÃO","b":true}]},{"tipo":"p","c":"↓"},{"tipo":"p","c":[{"t":"CONTESTAÇÃO / REVISÃO, QUANDO APLICÁVEL","b":true}]},{"tipo":"p","c":"↓"},{"tipo":"p","c":[{"t":"ARQUIVO / MONITORIZAÇÃO","b":true}]},{"tipo":"h2","texto":"193. MATRIZ INDICATIVA DE INCIDENTES"},{"tipo":"h3","texto":"A. EMERGÊNCIA FÍSICA"},{"tipo":"p","c":"Exemplos:"},{"tipo":"lista","chave":"8","itens":[{"n":0,"c":"violência;"},{"n":0,"c":"emergência médica;"},{"n":0,"c":"incêndio;"},{"n":0,"c":"ameaça imediata."}]},{"tipo":"p","c":[{"t":"Primeiro passo:","b":true},{"t":" serviços de emergência."}]},{"tipo":"h3","texto":"B. RISCO DE SEGURANÇA ELEVADO"},{"tipo":"p","c":"Exemplos:"},{"tipo":"lista","chave":"1","itens":[{"n":0,"c":"ameaça;"},{"n":0,"c":"exploração;"},{"n":0,"c":"stalking;"},{"n":0,"c":"acesso não autorizado ao Espaço."}]},{"tipo":"p","c":[{"t":"Possível resposta:","b":true},{"t":" medida imediata + investigação."}]},{"tipo":"h3","texto":"C. FRAUDE FINANCEIRA"},{"tipo":"p","c":"Exemplos:"},{"tipo":"lista","chave":"4","itens":[{"n":0,"c":"pagamento falso;"},{"n":0,"c":"identidade falsa;"},{"n":0,"c":"refund fraudulento;"},{"n":0,"c":"chargeback abusivo."}]},{"tipo":"p","c":[{"t":"Possível resposta:","b":true},{"t":" bloqueio financeiro adequado + investigação."}]},{"tipo":"h3","texto":"D. SEGURANÇA DIGITAL"},{"tipo":"p","c":"Exemplos:"},{"tipo":"lista","chave":"2","itens":[{"n":0,"c":"Conta comprometida;"},{"n":0,"c":"phishing;"},{"n":0,"c":"malware;"},{"n":0,"c":"acesso suspeito."}]},{"tipo":"p","c":[{"t":"Possível resposta:","b":true},{"t":" limitação de Conta + autenticação/reverificação."}]},{"tipo":"h3","texto":"E. INCUMPRIMENTO SEM RISCO IMEDIATO"},{"tipo":"p","c":"Exemplos:"},{"tipo":"lista","chave":"5","itens":[{"n":0,"c":"Space Rules;"},{"n":0,"c":"informação incorreta;"},{"n":0,"c":"comportamento inadequado."}]},{"tipo":"p","c":[{"t":"Possível resposta:","b":true},{"t":" suporte, aviso, Resolution Centre ou outra política aplicável."}]},{"tipo":"h2","texto":"194. NÃO CONFUNDIR TRUST & SAFETY COM CUSTOMER SUPPORT"},{"tipo":"p","c":"Customer Support trata problemas operacionais gerais."},{"tipo":"p","c":"Trust & Safety deverá tratar prioritariamente questões relacionadas com:"},{"tipo":"p","c":"a) segurança;"},{"tipo":"p","c":"b) fraude;"},{"tipo":"p","c":"c) abuso;"},{"tipo":"p","c":"d) identidade;"},{"tipo":"p","c":"e) exploração;"},{"tipo":"p","c":"f) ameaças;"},{"tipo":"p","c":"g) riscos graves;"},{"tipo":"p","c":"h) integridade do marketplace."},{"tipo":"h2","texto":"195. NÃO CONFUNDIR TRUST & SAFETY COM RESOLUTION CENTRE"},{"tipo":"p","c":"O Resolution Centre trata principalmente conflitos transacionais."},{"tipo":"p","c":"Trust & Safety trata riscos de segurança e integridade."},{"tipo":"p","c":"Um caso poderá envolver ambos."},{"tipo":"h2","texto":"196. NÃO CONFUNDIR TRUST & SAFETY COM NOTICE & ACTION"},{"tipo":"p","c":"Notice & Action é o procedimento destinado a alegações de conteúdo ou oferta ilegal."},{"tipo":"p","c":"Trust & Safety tem um âmbito mais amplo e pode envolver:"},{"tipo":"p","c":"a) comportamento;"},{"tipo":"p","c":"b) segurança física;"},{"tipo":"p","c":"c) fraude;"},{"tipo":"p","c":"d) identidade;"},{"tipo":"p","c":"e) transações;"},{"tipo":"p","c":"f) incidentes."},{"tipo":"h2","texto":"197. NÃO CONFUNDIR TRUST & SAFETY COM POLÍCIA OU TRIBUNAL"},{"tipo":"p","c":"A Venue1Hub pode tomar decisões operacionais sobre a sua Plataforma."},{"tipo":"p","c":"Não substitui:"},{"tipo":"p","c":"a) autoridades policiais;"},{"tipo":"p","c":"b) serviços de emergência;"},{"tipo":"p","c":"c) tribunais;"},{"tipo":"p","c":"d) autoridades reguladoras."},{"tipo":"h2","texto":"198. RECONHECIMENTO DO UTILIZADOR"},{"tipo":"p","c":"Ao utilizar a Venue1Hub, o utilizador reconhece que:"},{"tipo":"p","c":"☐ Deve utilizar a Plataforma de forma segura e lícita."},{"tipo":"p","c":"☐ É responsável pelo comportamento que lhe seja imputável."},{"tipo":"p","c":"☐ Deve respeitar Space Rules e condições da Reserva."},{"tipo":"p","c":"☐ Não deve colocar deliberadamente pessoas ou bens em risco."},{"tipo":"p","c":"☐ Deve comunicar incidentes graves através dos canais adequados."},{"tipo":"p","c":"☐ Em emergência imediata deve contactar primeiro os serviços de emergência."},{"tipo":"p","c":"☐ A verificação de identidade não constitui garantia absoluta de segurança."},{"tipo":"p","c":"☐ A Venue1Hub poderá utilizar mecanismos de deteção de fraude e risco."},{"tipo":"p","c":"☐ Alguns mecanismos internos de segurança não serão divulgados publicamente."},{"tipo":"p","c":"☐ A Venue1Hub poderá aplicar medidas temporárias para proteger utilizadores ou a Plataforma."},{"tipo":"p","c":"☐ Incidentes poderão afetar Reservas, Listings, pagamentos ou Contas quando adequado."},{"tipo":"p","c":"☐ Violações graves ou repetidas poderão levar a suspensão ou encerramento."},{"tipo":"p","c":"☐ A Venue1Hub poderá conservar evidência necessária à investigação e cumprimento legal."},{"tipo":"p","c":"☐ A Venue1Hub poderá cooperar com autoridades quando legalmente necessário."},{"tipo":"h2","texto":"199. CONTACTOS"},{"tipo":"p","c":"Para questões de Trust & Safety ou para comunicar uma situação de segurança não emergente:"},{"tipo":"p","c":[{"t":"EdgeHub OÜ — Venue1Hub®\n","b":true},{"t":"E-mail: "},{"t":"mail@venue1hub.com\n","b":true},{"t":"Website:"},{"t":" www.venue1hub.com\n","href":"http://www.venue1hub.com/"},{"t":"Sede: Tallinn, Estónia"}]},{"tipo":"p","c":"Quando a situação esteja relacionada com uma Reserva específica, deverá ser utilizado, sempre que possível, o mecanismo disponível na respetiva Reserva para permitir associação ao Booking ID."},{"tipo":"p","c":[{"t":"Em caso de emergência física imediata, contacte diretamente os serviços de emergência competentes.","b":true}]},{"tipo":"p","c":[{"t":"VERSÃO 1.0 — 14-09-2026","b":true}]},{"tipo":"p","c":[{"t":"EdgeHub OÜ — Venue1Hub®","b":true}]}]};
